def semver_sort(versions):
    def parse(v):
        # strip build metadata
        main = v.split('+', 1)[0]
        if '-' in main:
            core, prerelease = main.split('-', 1)
        else:
            core, prerelease = main, None
        major, minor, patch = (int(x) for x in core.split('.'))
        if prerelease is None:
            pre_key = (1,)
        else:
            ids = prerelease.split('.')
            id_keys = []
            for ident in ids:
                if ident.isdigit():
                    id_keys.append((0, int(ident)))
                else:
                    id_keys.append((1, ident))
            pre_key = (0, id_keys)
        return (major, minor, patch, pre_key)

    return sorted(versions, key=parse)

